arguments.file_text:
.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

.catalog-sidebar h2 {
    margin-top: 0;
}

.filter-section {
    margin-bottom: 1.5rem;
}

.filter-section h3 {
    font-size: 0.95rem;
    margin-bottom: 0.5rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.3rem;
    cursor: pointer;
}

.filter-section label {
    display: block;
    margin-bottom: 0.4rem;
}

.filter-section input[type="number"] {
    width: 100%;
    padding: 0.3rem;
    margin-top: 0.2rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply,
.btn-clear {
